const fs = require('fs');
const os = require('os');
const path = require('path');
const dir = path.join(os.homedir(), '.n8n', 'persona');
const file = path.join(dir, 'users.json');
const seed = '{\n  "users": {},\n  "sessions": {},\n  "rateLimit": {}\n}';
fs.mkdirSync(dir, { recursive: true });
let content = seed;
try {
  const r = fs.readFileSync(file, 'utf-8');
  if (r && r.trim()) content = r; else fs.writeFileSync(file, seed);
} catch (e) {
  try { fs.writeFileSync(file, seed); } catch (_) {}
}

const j = $input.first().json || {};
return [{
  json: j,
  binary: { data: { data: Buffer.from(content, 'utf-8').toString('base64'), mimeType: 'application/json', fileName: 'users.json' } }
}];

const crypto = require('crypto');

const SESSION_TTL_MS = 1000 * 60 * 60 * 24 * 7;
const MAX_FAIL_PER_HOUR = 5;
const PASSWORD_MIN_LEN = 8;
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const TIME_RE = /^([01]?\d|2[0-3]):([0-5]\d)$/;

function hash(pw, salt) {
  return crypto.scryptSync(pw, salt, 64).toString('hex');
}
function newSalt() { return crypto.randomBytes(16).toString('hex'); }
function newToken() { return crypto.randomBytes(24).toString('hex'); }
function now() { return Date.now(); }

let users = { users: {}, sessions: {}, rateLimit: {} };
try {
  const bin = $input.first().binary && $input.first().binary.data;
  if (bin) {
    const buf = Buffer.from(bin.data, 'base64');
    const parsed = JSON.parse(buf.toString('utf-8'));
    if (parsed && typeof parsed === 'object') users = Object.assign(users, parsed);
  }
} catch (e) {  }

users.users = users.users || {};
users.sessions = users.sessions || {};
users.rateLimit = users.rateLimit || {};

const itemJson = $input.first().json || {};
const rawMsg = (itemJson.chatInput || itemJson.message || itemJson.input || '').toString().trim();
const sessionId = (itemJson.sessionId || itemJson.session_id || 'anon').toString();

const clientKey = sessionId;
const rl = users.rateLimit[clientKey] || { count: 0, windowStart: now() };
if (now() - rl.windowStart > 60 * 60 * 1000) { rl.count = 0; rl.windowStart = now(); }

function reject(msg) {
  users.rateLimit[clientKey] = rl;
  return { response: msg, users, shouldWrite: true };
}
function ok(msg, write = true) {
  users.rateLimit[clientKey] = rl;
  return { response: msg, users, shouldWrite: write };
}

if (!rawMsg) return [{ json: ok('Empty message. Type `help` for commands.', false) }];
if (rawMsg.length > 2000) return [{ json: reject('Message too long. Reject.') }];

function getActiveUser() {
  const s = users.sessions[sessionId];
  if (!s) return null;
  if (now() > s.expires) { delete users.sessions[sessionId]; return null; }
  return users.users[s.email] ? s.email : null;
}

const parts = rawMsg.split(/\s+/);
const cmd = parts[0].toLowerCase();
const rest = rawMsg.slice(parts[0].length).trim();

function bumpFail() {
  rl.count = (rl.count || 0) + 1;
  if (rl.count > MAX_FAIL_PER_HOUR) {
    return 'Too many failed attempts. Try again in 1 hour.';
  }
  return null;
}

if (cmd === 'help' || cmd === '?') {
  return [{ json: ok([
    'Persona commands:',
    '  register <email> <password>',
    '  login <email> <password>',
    '  logout',
    '  set interests <topic1, topic2, ...>',
    '     tech sub-categories: ai, frontend, security, gamedev, devops, startups, hardware',
    '     (general topics work too: world, science, business)',
    '  set schedule <HH:MM>',
    '  set email <new-email>',
    '  status',
    '  newsletter now',
    '  unsubscribe',
    '',
    'Privacy: your email is stored only to send newsletters. Use `unsubscribe` to erase.'
  ].join('\n'), false) }];
}

if (cmd === 'register') {
  const m = rest.match(/^(\S+)\s+(.+)$/);
  if (!m) return [{ json: reject('Usage: register <email> <password>') }];
  const [, email, password] = m;
  if (!EMAIL_RE.test(email)) return [{ json: reject('Invalid email.') }];
  if (password.length < PASSWORD_MIN_LEN) return [{ json: reject('Password must be at least 8 characters.') }];
  const key = email.toLowerCase();
  if (users.users[key]) return [{ json: reject('An account with that email already exists.') }];
  const salt = newSalt();
  users.users[key] = {
    email: key,
    salt,
    passwordHash: hash(password, salt),
    interests: [],
    schedule: null,
    role: 'user',
    createdAt: now(),
    lastSent: 0,
    consent: { storeEmail: true, sendNewsletter: true, consentedAt: now() }
  };
  const token = newToken();
  users.sessions[sessionId] = { email: key, token, expires: now() + SESSION_TTL_MS };
  return [{ json: ok(`Registered ${email}. You are logged in.\nNext: \`set interests ai, climate\` and \`set schedule 08:00\`.`) }];
}

if (cmd === 'login') {
  const m = rest.match(/^(\S+)\s+(.+)$/);
  if (!m) return [{ json: reject('Usage: login <email> <password>') }];
  const [, email, password] = m;
  const key = email.toLowerCase();
  const u = users.users[key];
  const fail = () => {
    const block = bumpFail();
    return [{ json: reject(block || 'Invalid credentials.') }];
  };
  if (!u) return fail();
  const candidate = hash(password, u.salt);
  if (candidate !== u.passwordHash) return fail();
  const token = newToken();
  users.sessions[sessionId] = { email: key, token, expires: now() + SESSION_TTL_MS };
  return [{ json: ok(`Logged in as ${key}.`) }];
}

const activeEmail = getActiveUser();
if (!activeEmail) {
  return [{ json: reject('Not authenticated. Use `register` or `login` first.') }];
}
const user = users.users[activeEmail];

if (cmd === 'logout') {
  delete users.sessions[sessionId];
  return [{ json: ok('Logged out.') }];
}

if (cmd === 'status') {
  return [{ json: ok([
    `Email:     ${user.email}`,
    `Interests: ${user.interests.length ? user.interests.join(', ') : '(none set)'}`,
    `Schedule:  ${user.schedule || '(none set)'}`,
    `Last sent: ${user.lastSent ? new Date(user.lastSent).toISOString() : 'never'}`
  ].join('\n'), false) }];
}

if (cmd === 'set') {
  const subParts = rest.split(/\s+/);
  const sub = (subParts[0] || '').toLowerCase();
  const subRest = rest.slice(sub.length).trim();
  if (sub === 'interests') {
    if (!subRest) return [{ json: reject('Usage: set interests <topic1, topic2, ...>') }];
    const list = subRest.split(/[,;]+/).map(s => s.trim().toLowerCase()).filter(Boolean).slice(0, 20);
    user.interests = list;
    return [{ json: ok(`Interests updated: ${list.join(', ')}`) }];
  }
  if (sub === 'schedule') {
    if (!TIME_RE.test(subRest)) return [{ json: reject('Usage: set schedule <HH:MM> (24h, UTC)') }];
    user.schedule = subRest;
    return [{ json: ok(`Schedule set to ${subRest} UTC daily.`) }];
  }
  if (sub === 'email') {
    if (!EMAIL_RE.test(subRest)) return [{ json: reject('Invalid email.') }];
    const newKey = subRest.toLowerCase();
    if (users.users[newKey] && newKey !== user.email) return [{ json: reject('Email already in use.') }];
    delete users.users[user.email];
    user.email = newKey;
    users.users[newKey] = user;
    users.sessions[sessionId].email = newKey;
    return [{ json: ok(`Email updated to ${newKey}.`) }];
  }
  return [{ json: reject('Unknown `set` subcommand. Try: set interests | set schedule | set email') }];
}

if (cmd === 'unsubscribe') {
  delete users.users[activeEmail];
  delete users.sessions[sessionId];
  return [{ json: ok('Account deleted. All personal data erased. Goodbye.') }];
}

if (cmd === 'newsletter') {
  if ((rest || '').toLowerCase() === 'now') {
    user._forceSend = true;
    return [{ json: ok('A newsletter will be queued on the next scheduled tick (within 1 hour). Use `set schedule` for daily delivery.') }];
  }
  return [{ json: reject('Usage: newsletter now') }];
}

return [{ json: reject('Unknown command. Type `help`.') }];

