const fs = require('fs');
const os = require('os');
const path = require('path');
const dir = path.join(os.homedir(), '.n8n', 'persona');
const file = path.join(dir, 'users.json');
const seed = '{\n  "users": {},\n  "sessions": {},\n  "rateLimit": {}\n}';
fs.mkdirSync(dir, { recursive: true });
let content = seed;
try {
  const r = fs.readFileSync(file, 'utf-8');
  if (r && r.trim()) content = r; else fs.writeFileSync(file, seed);
} catch (e) {
  try { fs.writeFileSync(file, seed); } catch (_) {}
}
return [{
  json: {},
  binary: { data: { data: Buffer.from(content, 'utf-8').toString('base64'), mimeType: 'application/json', fileName: 'users.json' } }
}];

let store = { users: {}, sessions: {}, rateLimit: {} };
try {
  const bin = $input.first().binary && $input.first().binary.data;
  if (bin) store = Object.assign(store, JSON.parse(Buffer.from(bin.data, 'base64').toString('utf-8')));
} catch(e) {}

const d = new Date();
const hh = d.getUTCHours().toString().padStart(2,'0');
const dayKey = d.toISOString().slice(0,10);

const due = [];
for (const [email, u] of Object.entries(store.users)) {
  if (!u.consent || !u.consent.sendNewsletter) continue;
  if (!u.interests || u.interests.length === 0) continue;
  const force = !!u._forceSend;
  const scheduled = u.schedule && u.schedule.startsWith(hh + ':');
  if (!force && !scheduled) continue;
  const lastDay = u.lastSent ? new Date(u.lastSent).toISOString().slice(0,10) : null;
  if (lastDay === dayKey && !force) continue;
  due.push({ email, interests: u.interests });
}

if (due.length === 0) {

  return [{ json: { _store: store, _empty: true } }];
}

return due.map(u => ({ json: { email: u.email, interests: u.interests, _store: store } }));

const items = $input.all();
const staticData = $getWorkflowStaticData('global');
const due = items.map(i => ({ email: i.json.email, interests: i.json.interests }));
staticData.due = due;
staticData.store = items[0] && items[0].json && items[0].json._store ? items[0].json._store : { users: {} };
return items;

const fs = require('fs');
const os = require('os');
const path = require('path');
const personaDir = path.join(os.homedir(), '.n8n', 'persona');
fs.mkdirSync(personaDir, { recursive: true });

const staticData = $getWorkflowStaticData('global');
const store = staticData.store || { users: {} };
const sentEmails = [];
for (const i of $input.all()) {
  const acc = i.json && i.json.accepted;
  if (Array.isArray(acc)) {
    for (const a of acc) {
      if (a) {
        sentEmails.push(a.toString().toLowerCase());
      }
    }
  }
}
const t = Date.now();
for (const e of sentEmails) {
  if (store.users[e]) {
    store.users[e].lastSent = t;
    delete store.users[e]._forceSend;
  }
}
staticData.store = store;
const payload = JSON.stringify(store, null, 2);
return [{
  json: { written: sentEmails.length },
  binary: {
    data: {
      data: Buffer.from(payload, 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'users.json'
    }
  }
}];

const fs = require('fs');
const os = require('os');
const path = require('path');
const dir = path.join(os.homedir(), '.n8n', 'persona');
const file = path.join(dir, 'users.json');
fs.mkdirSync(dir, { recursive: true });
const item = $input.first();
if (item.binary && item.binary.data) {
  fs.writeFileSync(file, Buffer.from(item.binary.data.data, 'base64'));
}
return [{ json: item.json }];

const items = $input.all();
const due = [];

for (const item of items) {
  const data = item.json;

  if (data && data._empty !== true && data.email) {
    due.push(item);
  }
}

return due;

const items = $input.all();
const built = [];

for (const item of items) {
  const data = item.json;

  if (data && data._nothing !== true && data.email && data.html) {
    built.push(item);
  }
}

return built;

const articles = $input.all().map(i => i.json).filter(a => a && (a.title || a.link));
const staticData = $getWorkflowStaticData('global');
const due = staticData.due || [];

const out = [];
for (const user of due) {
  for (const article of articles) {
    out.push({
      json: {
        email: user.email,
        interests: user.interests,
        title: article.title || '(untitled)',
        link: article.link || '#',
        snippet: (article.contentSnippet || article.content || article.description || '').toString().slice(0, 500),
      }
    });
  }
}
return out;

const item = $input.first().json;

let raw =
  item.text ??
  item.output ??
  item.response?.text ??
  item.response ??
  '';

raw = String(raw).trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '');

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start !== -1 && end !== -1 && end > start) {
  raw = raw.slice(start, end + 1);
}

raw = raw.replace(/"reason:\s*/g, '"reason":');

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { score: 0, reason: 'Could not parse model output' };
}

let score = Number(parsed.score);
if (!Number.isFinite(score)) score = 0;
score = Math.max(0, Math.min(10, Math.round(score)));

return [
  {
    json: {
      email: item.email,
      interests: Array.isArray(item.interests) ? item.interests : [],
      title: item.title || '(untitled)',
      link: item.link || '#',
      snippet: item.snippet || '',
      score,
      reason: parsed.reason || 'No reason returned'
    }
  }
];

const items = $input.all().map(i => i.json);
const grouped = {};

for (const item of items) {
  if (!grouped[item.email]) grouped[item.email] = [];
  grouped[item.email].push(item);
}

const out = [];

for (const [email, articles] of Object.entries(grouped)) {
  const ranked = articles
    .filter(a => a.score >= 4)
    .sort((a, b) => b.score - a.score)
    .slice(0, 8);

  if (!ranked.length) continue;

  const interests = ranked[0].interests || [];

  const htmlItems = ranked.map(a => `
    <li>
      <a href="${a.link}">${String(a.title).replace(/</g, '&lt;')}</a><br>
      <small>Score: ${a.score}/10 — ${String(a.reason).replace(/</g, '&lt;')}</small><br>
      <small>${String(a.snippet).replace(/</g, '&lt;').slice(0, 250)}</small>
    </li>
  `).join('');

  out.push({
    json: {
      email,
      subject: `Persona Briefing — ${new Date().toISOString().slice(0, 10)}`,
      html: `<!doctype html><html><body style="font-family:sans-serif;max-width:680px;margin:auto"><h2>Your Persona Briefing</h2><p>Topics: <em>${interests.join(', ')}</em></p><ul>${htmlItems}</ul><hr><p style="font-size:12px;color:#666">You receive this because you registered with Persona. To stop, send <code>unsubscribe</code> in the Persona chatbot.</p></body></html>`
    }
  });
}

return out;
